from pathlib import Path
import json,re
base=Path('outputs')
old=(base/'torekh-prototype.html').read_text(encoding='utf-8')
copy=old[old.index('const copy='):old.index("let lang='he'")]
profiles=json.loads((base/'verified-party-profiles.json').read_text(encoding='utf-8'))['profiles']
for i,p in enumerate(profiles):
    p['id']=p['source'].rsplit('/',1)[-1]
    p['active']='אינה מתמודדת' not in p['note'] and not p.get('withdrawal')
    p['source']=p['source'].replace('http:','https:')
    p['candidates']=[re.split(r'\n',x)[0].strip() for x in p['candidates']]
    p.pop('update',None)
policies={
'רק':{'source':'https://be-yahad.org.il/plans/','type':'Party plans; publication date not stated on overview','he':['מציעה להוריד את מחירי המזון ב־30% בתוך שלוש שנים באמצעות הגברת התחרות.','מציעה מסגרות מפוקחות ומסובסדות מגיל לידה והעדפה בהטבות לציבור המשרת והעובד.','מציעה 50% ייצוג נשים בדרג הבכיר, צמצום פערי שכר ומאבק באלימות נגד נשים.'],'en':['Proposes cutting food prices by 30% within three years through increased competition.','Proposes supervised, subsidized childcare from birth and priority benefits for people who serve and work.','Proposes 50% representation of women in senior roles, reducing pay gaps and tackling violence against women.'],'ar':['تقترح خفض أسعار الغذاء بنسبة 30% خلال ثلاث سنوات عبر زيادة المنافسة.','تقترح أطر رعاية خاضعة للرقابة ومدعومة منذ الولادة وأولوية في المزايا لمن يخدمون ويعملون.','تقترح تمثيل النساء بنسبة 50% في المناصب العليا وتقليص فجوات الأجور ومكافحة العنف ضد النساء.']},
'דרך':{'source':'https://yasharwitheisenkot.com/agenda_point/','type':'Ten-point party plan; publication date not stated','he':['מציעה חוק שירות ממלכתי לכל ושילוב הציבור החרדי והערבי במסגרות שירות מתאימות.','מציעה חיזוק התחרות והעדפה בהטבות דיור ומס למי שנושא בנטל הביטחוני והכלכלי.','מתחייבת למערכת משפט עצמאית, זכויות מיעוט והגבלת כהונת ראש הממשלה לשתי קדנציות.'],'en':['Proposes a national-service law for all, including suitable service frameworks for Haredi and Arab citizens.','Proposes stronger competition and priority housing and tax benefits for those carrying security and economic responsibilities.','Commits to judicial independence, minority rights and a two-term limit for the prime minister.'],'ar':['تقترح قانون خدمة عامة للجميع يشمل أطرًا ملائمة للمواطنين الحريديم والعرب.','تقترح تعزيز المنافسة وأولوية في مزايا السكن والضرائب لمن يتحملون الأعباء الأمنية والاقتصادية.','تلتزم باستقلال القضاء وحقوق الأقليات وتحديد ولاية رئيس الحكومة بفترتين.']},
'אמת':{'source':'https://democrats.org.il/wp-content/uploads/2026/04/vision0426.pdf','type':'Party principles, April 2026','he':['מציעה חינוך ממלכתי עם ליבה משותפת ושוויון הזדמנויות, תוך אפשרות לתכנים תרבותיים ודתיים ייחודיים.','מציעה שוויון זכויות מגדרי, דתי ולאומי ושילוב נשים ומיעוטים בשירות הציבורי ובהנהגה.','מציעה לבטל פטורים משירות צבאי לפי החוק הקיים ולפתח גם מסלולי שירות לאומי־אזרחי.'],'en':['Proposes public education with a shared core and equal opportunities, allowing distinct cultural and religious content.','Proposes gender, religious and national equality and wider participation of women and minorities in public service and leadership.','Proposes ending exemptions under existing military-service law and developing national-civilian service pathways.'],'ar':['تقترح تعليمًا رسميًا بمنهاج أساسي مشترك وتكافؤ الفرص مع إتاحة مضامين ثقافية ودينية خاصة.','تقترح مساواة جندرية ودينية وقومية وتوسيع مشاركة النساء والأقليات في الخدمة العامة والقيادة.','تقترح إلغاء الإعفاءات بموجب قانون الخدمة العسكرية القائم وتطوير مسارات خدمة وطنية مدنية أيضًا.']},
'ל':{'source':'https://beytenu.org.il/party-platform/','type':'Party platform; page publication date not stated','he':['מציעה חוקה, הפרדת דת ומדינה ונישואים וגירושים אזרחיים.','מציעה שירות צבאי או אזרחי לכל בני ובנות 18, הגברת תחרות וצמצום רגולציה.','מציעה תקצוב רב־שנתי למניעת אלימות במשפחה והרחבת טיפול בנפגעות ובנפגעי תקיפה מינית.'],'en':['Proposes a constitution, separation of religion and state, and civil marriage and divorce.','Proposes military or civilian service for all 18-year-olds, increased competition and reduced regulation.','Proposes multiyear funding against domestic violence and expanded care for survivors of sexual assault.'],'ar':['تقترح دستورًا وفصل الدين عن الدولة والزواج والطلاق المدنيين.','تقترح خدمة عسكرية أو مدنية لجميع من يبلغون 18 عامًا وتعزيز المنافسة وتقليل التنظيم.','تقترح تمويلًا متعدد السنوات لمكافحة العنف الأسري وتوسيع علاج الناجيات والناجين من الاعتداء الجنسي.']},
'ודם':{'source':'https://jointlist.org.il/he/platform/','type':'Party platform explicitly identifies the 26th Knesset election','he':['מציעה סיום הכיבוש והקמת מדינה פלסטינית, לצד זכויות לאומיות ואזרחיות לציבור הערבי.','מציגה מאבק בפשיעה ובאלימות, שוויון מגדרי וחיזוק שירותי בריאות וחינוך כנושאי עדיפות.','מציעה מיסוי פרוגרסיבי והרחבת השירותים הציבוריים; אלה הצעות המפלגה, לא תוצאות שהוכחו.'],'en':['Proposes ending the occupation and establishing a Palestinian state, alongside national and civil rights for Arab citizens.','Prioritizes combating crime and violence, gender equality, and stronger health and education services.','Proposes progressive taxation and expanded public services. These are party proposals, not demonstrated outcomes.'],'ar':['تقترح إنهاء الاحتلال وإقامة دولة فلسطينية إلى جانب الحقوق القومية والمدنية للجمهور العربي.','تعطي أولوية لمكافحة الجريمة والعنف والمساواة الجندرية وتعزيز خدمات الصحة والتعليم.','تقترح ضرائب تصاعدية وتوسيع الخدمات العامة. هذه مقترحات القائمة وليست نتائج مثبتة.']},
'ני':{'source':'https://www.noamlisrael.org.il/','type':'Party website principles; publication date not stated','he':['מציעה חיזוק הצביון היהודי במערכות המדינה, שמירת שבת ציבורית וחיזוק הרבנות הראשית.','מציעה פסקת התגברות, פיצול תפקיד היועץ המשפטי לממשלה והרחבת מינויי האמון.','מציעה חינוך יהודי וציוני, זכות וטו להורים על תכנים ושכר של לפחות 12,000 ש״ח למורה מתחיל.'],'en':['Proposes strengthening Jewish identity in state institutions, public Sabbath observance and the Chief Rabbinate.','Proposes an override clause, splitting the attorney-general role and expanding political appointments.','Proposes Jewish and Zionist education, a parental veto on content and a minimum starting teacher salary of NIS 12,000.'],'ar':['تقترح تعزيز الهوية اليهودية في مؤسسات الدولة والحفاظ على السبت في المجال العام وتعزيز الحاخامية الرئيسية.','تقترح بند تجاوز قضائي وتقسيم منصب المستشار القانوني للحكومة وتوسيع التعيينات السياسية.','تقترح تعليمًا يهوديًا وصهيونيًا وحق اعتراض للأهل على المضامين وراتبًا ابتدائيًا للمعلمين لا يقل عن 12,000 شيكل.']},
'ך':{'source':'https://amchaisrael.co.il/foundations','type':'Party founding principles; publication date not stated','he':['מציעה הכרעה צבאית מהירה, גביית מחיר טריטוריאלי מהאויב ותוכנית המוגדרת באתר כהגירה מרצון מעזה בהסכמות בין־לאומיות.','מציעה שירות צבאי או לאומי משמעותי, עם תגמול לפי סוג השירות, משכו ורמת הסיכון.','מציעה חיזוק אזורי גבול, ביזור סמכויות לרשויות המקומיות וגוף לאומי לתיאום המאבק בפשיעה.'],'en':['Proposes rapid military victory, territorial penalties against enemies and a Gaza emigration program described by the party as voluntary and internationally agreed.','Proposes military or meaningful national service, with rewards based on service type, duration and risk.','Proposes strengthening border regions, decentralizing powers to local authorities and a national body coordinating action against crime.'],'ar':['تقترح حسمًا عسكريًا سريعًا وأثمانًا إقليمية تُفرض على العدو وبرنامج هجرة من غزة تصفه الحركة بالطوعي وباتفاقات دولية.','تقترح خدمة عسكرية أو وطنية فعلية مع مكافآت بحسب نوع الخدمة ومدتها ومخاطرها.','تقترح تعزيز مناطق الحدود ونقل صلاحيات للسلطات المحلية وهيئة وطنية لتنسيق مكافحة الجريمة.']}}
policies['צף']={'source':'https://piratim.org/wiki/matza/','type':'Party wiki platform; publication date not stated','he':['מציעה דמוקרטיה השתתפותית, שקיפות בקבלת החלטות והגנה על פרטיות וחופש הביטוי.','מציעה ביטול אחוז החסימה ואינטרנט חינם לכל.','מציעה לגליזציה של קנאביס ושירותי חינוך, בריאות ורווחה לאורך החיים.'],'en':['Proposes participatory democracy, transparent decision-making, privacy protection and freedom of expression.','Proposes abolishing the electoral threshold and free internet access for all.','Proposes cannabis legalization and lifelong education, health and welfare services.'],'ar':['تقترح ديمقراطية تشاركية وشفافية اتخاذ القرار وحماية الخصوصية وحرية التعبير.','تقترح إلغاء نسبة الحسم وإتاحة الإنترنت مجانًا للجميع.','تقترح تقنين القنب وخدمات التعليم والصحة والرفاه طوال الحياة.']}
policies['נקי']={'source':'https://hatikun.org.il/מטרות-התיקון/','type':'Party objectives; publication date not stated','he':['מציעה בחירה אישית ואזורית לנציגי הכנסת במקום רשימות מפלגתיות סגורות.','מציעה מינוי ראש ממשלה ושרים לפי התאמה מקצועית ויעדי ביצוע.','מציעה חוקה המבוססת על שוויון וחירות, וכן התניית זכות הבחירה בעמידה בחובת תרומה למדינה.'],'en':['Proposes individual, regional election of Knesset representatives instead of closed party lists.','Proposes choosing the prime minister and ministers by professional suitability and performance targets.','Proposes a constitution based on equality and liberty, and making voting rights conditional on fulfilling a duty to contribute to the state.'],'ar':['تقترح انتخابًا فرديًا ومناطقيًا لممثلي الكنيست بدل القوائم الحزبية المغلقة.','تقترح اختيار رئيس الحكومة والوزراء بحسب الملاءمة المهنية وأهداف الأداء.','تقترح دستورًا قائمًا على المساواة والحرية واشتراط حق التصويت بأداء واجب المساهمة في الدولة.']}
policies=json.loads(Path('work/audited-policy-data.json').read_text(encoding='utf-8'))
data={'checked':'2026-10-24','sourceUpdated':'2026-10-22','source':'https://www.gov.il/he/pages/candidates-lists-26','ballots':'https://www.gov.il/he/pages/candidates-lists-26?chapterIndex=2','profiles':profiles,'policies':policies}
(base/'party-card-data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
template=Path('work/guide-shell.html').read_text(encoding='utf-8')
if '/*HERO_COPY*/' in template:
    template=template.replace('/*HERO_COPY*/','const HERO_COPY='+json.dumps(json.loads(Path('outputs/hero-translations.json').read_text(encoding='utf-8')),ensure_ascii=False)+';')
translation_file=Path('outputs/party-translations.json')
if translation_file.exists():
    template=re.sub(r'const PARTY_TRANSLATIONS=.*?;\nconst localeUi=',lambda _: 'const PARTY_TRANSLATIONS='+json.dumps(json.loads(translation_file.read_text(encoding='utf-8')),ensure_ascii=False)+';\nconst localeUi=',template,count=1,flags=re.S)
template=template.replace('/*INTRODUCTION_DATA*/','const PARTY_INTRODUCTIONS='+json.dumps(json.loads(Path('outputs/party-introductions.json').read_text(encoding='utf-8'))['records'],ensure_ascii=False)+';')

template=template.replace('/*IDENTITY_DATA*/','const PARTY_IDENTITIES='+json.dumps(json.loads(Path('outputs/party-identity-badges.json').read_text(encoding='utf-8'))['records'],ensure_ascii=False)+';')
template=template.replace('/*COALITION_DATA*/','const COALITION='+json.dumps(json.loads(Path('outputs/coalition-statements.json').read_text(encoding='utf-8')),ensure_ascii=False)+';')
template=template.replace('/*COPY*/',copy).replace('/*DATA*/','const DATA='+json.dumps(data,ensure_ascii=False)+';')
template=template.replace('7 תקצירי','9 תקצירי').replace('7 short','9 short').replace('و7 ملخصات','و9 ملخصات')
(base/'torekh-guide.html').write_text(template,encoding='utf-8')
print(f'Built {len(profiles)} entries; {sum(p["active"] for p in profiles)} active; {len(policies)} primary-source policy summaries.')
